// Route112_CableCarStation (zone 555): generated by converter/gen_interiors.py from Sapphire's simple people and signs.
// Messages: src/text/script/0356_room_Route112_CableCarStation.txt
#include "asm/field_script.inc"
#include "hoenn.h"
#include "hoenn_trainers.h"
#include "hoenn_story.inc"

    ScriptEntry Script_None
    ScriptEntry CC_Attendant    // 2: the attendant (Route112_CableCarStation_EventScript_15C08C), ch5
    ScriptEntry CC_Arrive       // 3: the arrival (reserved by the ride; Sapphire OnFrame, VAR_CABLE_CAR_STATION_STATE 2)
    ScriptEntry CC_Init         // 4: zone init (Sapphire OnTransition)
    ScriptEntriesEnd

Script_None:
    VMHalt
    .balign 4, 0
// ---- story
// Chapter Ch5 (ch5 agent, 2026-10-07; Sapphire data/maps/Route112_CableCarStation/scripts.inc): the cable car up. The attendant =
// data/story/ch5.json uid 1 (Sapphire object 1; its cable car object has no Black 2 sprite). Room tile = Sapphire
// tile + (1, 0). Map scripts: 1111_room_Route112_CableCarStation_init.s (zone init = 4; Sapphire's OnFrame arrival, state 2 -> 3, is the ride's reserved script:
// Black 2 starts it on the black screen after the warp, RTReserveScript, as its own scripted warps do).
// The ride: Black 2 has no cable car scene (Sapphire's special CableCar draws the car crossing Route 112): the
// screen fades to black, Black 2's elevator hum (SEQ_SE_FLD_23, its elevators' ride sound) plays for 3 seconds, then
// the player arrives in the other station (special CableCarWarp: Sapphire tile (6,4)), where the arrival scene runs.
// Text: src/text/script/ lines 0-2 (ready / step this way / another time).
#define CC_ATTENDANT 1

CC_Attendant:                                    // Route112_CableCarStation_EventScript_15C08C
    h_lock
    SEPlay SEQ_SE_MESSAGE
    h_faceplayer
    h_yesno 0, HLIB_TMP                          // The Cable Car is ready to go up. Would you like to be on it?
    h_goto_if_no HLIB_TMP, L_CC_No
    h_msgbox 1                                   // Please step this way.
    h_closemessage
    h_applymovement CC_ATTENDANT, Mv_CC_AttendantRide
    h_applymovement 255, Mv_CC_PlayerRide
    h_waitmovement
    h_setvar VAR_CABLE_CAR_STATION_STATE, 1       // (setvar VAR_0x8004 + incrementgamestat: none)
    // special CableCarWarp + special CableCar: the ride (fade, elevator hum, warp), then the arrival = script 3 on the
    // black screen, at Sapphire (6,4) of the other station, facing down
    h_ride_cable_car 340, 7, 4, 1, 3
    h_release
L_CC_No:
    h_msgbox 2                                   // Please ride with us another time.
    h_release

CC_Arrive:                                       // (fade in) Route112_CableCarStation_EventScript_15C068
    h_lock
    FadeInBlack
    FadeWait
    h_applymovement 255, Mv_CC_PlayerArrive
    h_applymovement CC_ATTENDANT, Mv_CC_AttendantArrive
    h_waitmovement
    h_setvar VAR_CABLE_CAR_STATION_STATE, 0      // (setobjectxyperm 1, 6, 7 + FACE_DOWN: back where it stands)
    h_release

CC_Init:                                         // Route112_CableCarStation_MapScript1_15C03E (setescapewarp: none)
    h_goto_if_ne VAR_CABLE_CAR_STATION_STATE, 2, L_CC_InitDone
    ObjInitNPCGPos 0, 2, 8, 0, 4       // setobjectxyperm 1, 7, 4 (the attendant beside the car)
L_CC_InitDone:
#ifdef HOENN_TEST_CH5
    VMCall Test_Ch5Start
#endif
    VMHalt

    .balign 4, 0
Mv_CC_AttendantRide:
    walk_up 2
    walk_right
    walk_in_place_fastest_left
    step_end
Mv_CC_PlayerRide:
    walk_up 3
    delay_16
    step_end
Mv_CC_PlayerArrive:
    walk_down 3
    delay_16
    step_end
Mv_CC_AttendantArrive:
    delay_16
    walk_left
    walk_down 2
    step_end
#ifdef HOENN_TEST_CH5
#include "scenes/ch5_test.inc"
#endif
